INSERT INTO "beauty_tip_categories" ("id","name","short_label","color","anchor_x","anchor_y","label_side","issue_tags","sort_order") VALUES('sensitivity','Sensitivity & Redness','Redness',4293227379,0.55,0.5,'right','["redness", "flushing", "irritation"]',5);
