INSERT INTO "beauty_tip_categories" ("id","name","short_label","color","anchor_x","anchor_y","label_side","issue_tags","sort_order") VALUES('uneven_tone','Uneven Skin Tone','Uneven tone',4291142515,0.65,0.55,'right','["blotchiness", "patchy tone", "discoloration"]',8);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('7b13d0ebdf11b8b030cd0b1275743722','acne','high','Try a raw honey mask','Many people in the beauty community apply a thin layer of raw honey for 20–30 minutes before rinsing. Some say it helped calm painful breakouts over a few weeks of consistent use.',1);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('f04848ad0a579d9f35918da18a6ee8e4','acne','high','Gentle cold compress','Wrapping an ice cube in a clean cloth and pressing it gently on swollen spots for a few minutes may help reduce redness. Creators often mention this before filming.',2);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('b1d18525a9f3cf3bc3c4a2544c53976e','acne','high','Diluted apple cider vinegar toner','Mix one part apple cider vinegar with three parts water, dab with a cotton pad after cleansing, and see how your skin responds. Start once a day.',3);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('fa2ca5faa9ccaeb6ca7afeb58f56cb67','acne','high','Simplify your routine','When breakouts flare up, many people strip back to a gentle cleanser and lightweight moisturizer for two to three weeks to reduce irritation.',4);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('a99c9457a47463f8af00006127b6cdb8','acne','medium','Spot treat with tea tree oil','Dilute a drop of tea tree oil and dab on individual spots with a cotton swab. Many creators share this as an overnight trick that may reduce redness by morning.',1);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('d7a4baa432042364e6020cf0889a207e','acne','medium','Green tea toner','Brew green tea, cool it, and use it as a toner. Some users say regular use made mild breakouts look less noticeable over time.',2);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('76b33562cd0a6336039193c348cc0449','acne','medium','Wash pillowcases often','Switching to a clean cotton pillowcase every two to three days is a simple habit many creators credit for fewer cheek and jawline breakouts.',3);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('3ad06b405e5963b35ac3465e5cf010d6','acne','medium','Clay mask once a week','A weekly clay or charcoal mask may help with congestion. People often say skin looks cleaner after regular use.',4);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('abc45bec4b78ccf546d7b62f83c84f10','acne','low','Lukewarm water cleanse','Many people say switching to lukewarm water and a gentle cleanser morning and night helped occasional breakouts over time.',1);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('e9223fd40525a4c128e787ac43d6e64d','acne','low','Rice water rinse','Soak rice in water for 15–20 minutes, strain, and rinse your face. Asian beauty creators often share this for a clearer-looking complexion.',2);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('ac60611b04698227ba977f2cf9a4e36c','acne','low','Hands off your face','Being mindful about not touching your face through the day may reduce how often new spots appear, according to many users.',3);
INSERT INTO "beauty_tip_entries" ("id","category_id","severity","title","body","sort_order") VALUES('633f253294051626fd687e596fcf0bbb','acne','low','Aloe vera gel moisturizer','Pure aloe vera gel is a fan favourite for lightweight hydration that some say helps keep occasional breakouts calmer.',4);
